// Carrossel avulso (ex.: apresentação da Gabi). Protegido pelo convite (config.yt_convite).
async function publicarCarrossel(k: string, corpo: { imagens?: string[]; legenda?: string }) {
  const { data: c } = await db.from("config").select("valor").eq("chave", "yt_convite").maybeSingle();
  if (!c?.valor || k !== c.valor) return { erro: "convite inválido" };
  const imgs = (corpo.imagens ?? []).slice(0, 10);
  if (imgs.length < 2 || !corpo.legenda) return { erro: "precisa de 2+ imagens e legenda" };
  const token = await tokenAtual();
  const eu = await ig("/me", token, { fields: "user_id" });
  const filhos: string[] = [];
  for (const url of imgs) filhos.push((await ig(`/${eu.user_id}/media`, token, { image_url: url, is_carousel_item: "true" }, "POST")).id);
  const cont = await ig(`/${eu.user_id}/media`, token, { media_type: "CAROUSEL", children: filhos.join(","), caption: corpo.legenda }, "POST");
  for (let i = 0; i < 20; i++) {
    const st = await ig(`/${cont.id}`, token, { fields: "status_code" });
    if (st.status_code === "FINISHED") break;
    if (st.status_code === "ERROR") throw new Error("carrossel: erro no processamento");
    await new Promise((r) => setTimeout(r, 3000));
  }
  const pub = await ig(`/${eu.user_id}/media_publish`, token, { creation_id: cont.id }, "POST");
  await registrar("feed", "carrossel", "carrossel avulso", undefined, pub.id);
  const link = await ig(`/${pub.id}`, token, { fields: "permalink" }).catch(() => ({}));
  return { ok: true, id: pub.id, link: link.permalink };
}

